CREATE TEMP TABLE rsvp_content ON COMMIT DROP AS
SELECT (item->>'id')::uuid id, (item->>'exerciseId')::uuid exercise_id,
  (item->>'ageGroupId')::uuid age_id, (item->>'level')::int level,
  item->>'title' title, item->>'content' content, (item->>'wordCount')::int word_count,
  item->'questions' questions
FROM jsonb_array_elements($content$[
  {
    "id": "883ab0fa-847a-5b42-8f37-c65584416efc",
    "exerciseId": "09061d36-37ce-5719-ab5d-8e8c01c326fa",
    "ageGroupId": "10000000-0000-0000-0000-000000000001",
    "age": "child",
    "level": 4,
    "title": "Bir bahçede ortak gözlem — Çocuk Seviye 4 seri sunum",
    "content": "Okul bahçesinin bir köşesinde boş bir toprak alan vardı. Eren, arkadaşlarıyla birlikte burada küçük bir bitki köşesi kurmayı düşündü. İlk işleri tohum almak olmadı. Önce alanı gezdiler, güneşin nereden geldiğini ve suyun nerede biriktiğini gözlemlediler.\n\nÖğretmenleri, her bitkinin aynı yerde aynı biçimde büyümeyeceğini söyledi. Çocuklar sabah ve öğleden sonra bahçeye baktı. Gölgenin gün içinde yer değiştirdiğini fark ettiler. Bir deftere tarih ve saat yazarak gördüklerini kısa cümlelerle kaydettiler.\n\nBahçenin kenarında kuru yapraklar ve birkaç taş bulunuyordu. Çocuklar toprağı temizlerken küçük canlıları rahatsız etmemeye çalıştı. Buldukları her şeyi çöp saymadılar. Bazı yaprakların ve dalların toprağın üzerinde doğal olarak bulunabileceğini öğretmenlerine sordular.\n\nTohumları seçerken yetişme sürelerini de okudular. Bazı bitkilerin daha çok zaman istediğini gördüler. Küçük alan için birkaç türle başlamaya karar verdiler. Her sıranın başına bir işaret koydular. İşaretlerde bitkinin adı ve ekildiği gün yazıyordu.\n\nİlk sulamada herkes su vermek istedi. Ancak her çocuğun ayrı ayrı sulaması toprağı fazla ıslattı. Ertesi gün görevleri paylaşmaya karar verdiler. Bir kişi suluyor, bir kişi toprağın durumunu gözlüyor, bir kişi de deftere not alıyordu.\n\nBir hafta sonra ilk küçük yapraklar göründü. Eren, bütün tohumların aynı gün filizlenmediğini fark etti. Henüz görünmeyen tohumları hemen başarısız saymadı. Paket üzerindeki bilgilerle defterdeki tarihleri karşılaştırdı. Gözlem yapmanın bazen sabır gerektirdiğini anladı.",
    "wordCount": 202,
    "sourceTextId": "c4a10000-0000-5000-8000-000000000001",
    "questions": [
      {
        "id": "4f097b5c-bdbf-5b1b-8cf1-b16624532557",
        "questionText": "Bitki köşesi nerede kurulacaktı?",
        "type": 1,
        "bloomLevel": 1,
        "explanation": "İlk paragraf çalışmanın okul bahçesinin boş köşesinde yapılacağını açıkça söyler.",
        "optionA": "Okul bahçesindeki boş toprak alanda",
        "optionB": "Sınıfın pencere önündeki rafta",
        "optionC": "Spor salonunun girişindeki alanda",
        "optionD": "Okul binasının çatı katında",
        "correctAnswer": "A",
        "evidence": "Okul bahçesinin bir köşesinde boş bir toprak alan vardı.",
        "orderIndex": 0
      },
      {
        "id": "b8dea866-4a06-577f-827b-a322923593ec",
        "questionText": "Çocuklar tohum almadan önce ne yaptı?",
        "type": 1,
        "bloomLevel": 1,
        "explanation": "Tohum seçimi ilk iş değildir; önce yetiştirme alanının koşulları incelenir.",
        "optionA": "Bütün bitkileri aynı sıraya yerleştirdi",
        "optionB": "Alanı gezip güneş ve su koşullarını gözledi",
        "optionC": "Bahçedeki her ağacı tek tek ölçtü",
        "optionD": "Yetişmiş bitkileri sınıfa taşıdı",
        "correctAnswer": "B",
        "evidence": "Önce alanı gezdiler, güneşin nereden geldiğini ve suyun nerede biriktiğini gözlemlediler.",
        "orderIndex": 1
      },
      {
        "id": "d3115bed-c898-5442-8cba-da9cf51c8e3b",
        "questionText": "Sabah ve öğleden sonra bahçeye bakmak hangi değişikliği gösterdi?",
        "type": 1,
        "bloomLevel": 1,
        "explanation": "Metin iki zamanlı gözlemin sonucunu gölgenin konumunun değişmesi olarak belirtir.",
        "optionA": "Bütün bitkilerin aynı gün filizlendiğini",
        "optionB": "Taşların gece boyunca kaybolduğunu",
        "optionC": "Gölgenin gün içinde yer değiştirdiğini",
        "optionD": "Tohumların sayısının her saat arttığını",
        "correctAnswer": "C",
        "evidence": "Gölgenin gün içinde yer değiştirdiğini fark ettiler.",
        "orderIndex": 2
      },
      {
        "id": "62285288-1d9a-5093-814d-7304b1e26c41",
        "questionText": "Sıra başındaki işaretlerde hangi bilgiler vardı?",
        "type": 1,
        "bloomLevel": 1,
        "explanation": "İşaretler hangi bitkinin ne zaman ekildiğini takip etmeyi sağlar.",
        "optionA": "Bitkinin fiyatı ve satın alındığı dükkân",
        "optionB": "Sulayan öğrencinin adı ve sınıf notu",
        "optionC": "Bahçenin boyu ve okulun açılış tarihi",
        "optionD": "Bitkinin adı ve ekildiği gün",
        "correctAnswer": "D",
        "evidence": "İşaretlerde bitkinin adı ve ekildiği gün yazıyordu.",
        "orderIndex": 3
      },
      {
        "id": "a4235742-2158-5cb6-88fc-d15650f8fbb6",
        "questionText": "İlk sulamadan sonra görev paylaşımı neden gerekli görüldü?",
        "type": 2,
        "bloomLevel": 2,
        "explanation": "Aşırı sulama ortak işin düzenlenmediğini gösterir; görev paylaşımı tekrarını önlemeye yöneliktir.",
        "optionA": "Aynı işi herkes yapınca gereğinden fazla su verilmişti",
        "optionB": "Çocukların hiçbirisi sulamaya katılmak istememişti",
        "optionC": "Öğretmen bahçenin tamamen kapatılmasını istemişti",
        "optionD": "Tohumların hepsi ilk gün kuruyup yok olmuştu",
        "correctAnswer": "A",
        "evidence": "her çocuğun ayrı ayrı sulaması toprağı fazla ıslattı",
        "orderIndex": 4
      }
    ]
  },
  {
    "id": "fa8d9820-d431-5a40-8552-d5c2273b3902",
    "exerciseId": "09061d36-37ce-5719-ab5d-8e8c01c326fa",
    "ageGroupId": "10000000-0000-0000-0000-000000000001",
    "age": "child",
    "level": 4,
    "title": "Yol gösteren harita — Çocuk Seviye 4 seri sunum",
    "content": "Deniz, evinden parka giderken her zaman aynı yolu kullanıyordu. Bir gün yolun bir bölümü kapandı. Başka bir sokaktan yürümek zorunda kaldı. Dönüşte basit bir harita çizdi. Haritada bildiği yerleri, köşeleri ve geçtiği sokakları işaretledi.\n\nHaritası gerçek sokakların tam ölçüsünü göstermiyordu. Bazı yolları uzun, bazılarını kısa çizmişti. Yine de nerede döneceğini hatırlamasına yardım ediyordu. Deniz, bir çizimin bütün ayrıntıları göstermeden de belirli bir iş için yararlı olabileceğini gördü.\n\nArkadaşı haritaya baktığında fırının işaretini hemen tanıdı. Ancak iki oyun alanını birbirine karıştırdı. Deniz, aynı şekli iki farklı yer için kullanmıştı. İşaretlerin yanına kısa adlar ekledi. Böylece çizim, yalnız kendisinin anlayacağı bir not olmaktan çıktı.\n\nBir sonraki yürüyüşte yolun süresini de tuttu. Hızlı yürüdüğü günle arkadaşlarıyla konuşarak yürüdüğü gün aynı sonucu vermedi. Tek bir süreyi kesin bir ölçü saymadı. Haritanın yanına, sürenin yürüyüş biçimine göre değişebileceğini yazdı.\n\nParkın kapısında başka bir harita vardı. Bu harita yürüyüş yollarını, çeşmeleri ve oturma alanlarını gösteriyordu. Deniz iki haritanın aynı şey olmadığını fark etti. Kendi haritası parka ulaşmaya, kapıdaki harita ise parkın içinde dolaşmaya yardım ediyordu.\n\nParkta küçük bir keşif oyunu hazırladılar. Arkadaşları üç yeri bulacak ve oralardaki işaretleri not edecekti. Oyunda koşmak zorunlu değildi. Deniz, yolların açık olduğundan emin olmak için oyunu önce bir arkadaşıyla yavaşça denedi.",
